def truncate_number(number: float) -> float:
    """Return the decimal part of a positive floating point number."""
    return number - int(number)

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def max_value_on_paths(N: int, grid_values: list) -> int:
    # Build grid with 1-indexing
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        grid[x][y] = val

    # Edge case: single cell
    if N == 1:
        return grid[1][1]

    # Initialize DP arrays
    NEG_INF = -10**9
    dp = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
    dp[1][1] = grid[1][1]

    # Iterate over steps t = i1 + j1 = i2 + j2
    for t in range(2, 2 * N + 1):
        newdp = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
        i_min = max(1, t - N)
        i_max = min(N, t - 1)
        for i1 in range(i_min, i_max + 1):
            j1 = t - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(i_min, i_max + 1):
                j2 = t - i2
                if j2 < 1 or j2 > N:
                    continue
                best = NEG_INF
                # transitions: each path can come from up or left
                for di1 in (0, 1):
                    for di2 in (0, 1):
                        pi1 = i1 - di1
                        pi2 = i2 - di2
                        if pi1 < 1 or pi2 < 1:
                            continue
                        best = max(best, dp[pi1][pi2])
                if best == NEG_INF:
                    continue
                val = grid[i1][j1]
                if i1 != i2 or j1 != j2:
                    val += grid[i2][j2]
                newdp[i1][i2] = best + val
        dp = newdp

    return dp[N][N] if dp[N][N] != NEG_INF else 0

def calculate_scholarship(grades: List[int], leader: str, west: str, papers: int) -> int:
    avg, class_eval = grades
    scholarship = 0
    if avg > 80 and papers >= 1:
        scholarship += 8000
    if avg > 85 and class_eval > 80:
        scholarship += 4000
    if avg > 90:
        scholarship += 2000
    if avg > 85 and west == 'Y':
        scholarship += 1000
    if class_eval > 80 and leader == 'Y':
        scholarship += 850
    return scholarship

def verify_isbn(isbn: str) -> str:
    parts = isbn.split('-')
    if len(parts) != 4:
        return isbn  # invalid format, return as is
    digits = []
    for i, part in enumerate(parts):
        if i == 3:  # checksum part
            if part == 'X':
                digits.append(10)
            else:
                digits.append(int(part))
        else:
            # each part may contain multiple digits
            for ch in part:
                digits.append(int(ch))
    if len(digits) != 10:
        return isbn  # invalid number of digits
    total = sum((i + 1) * d for i, d in enumerate(digits))
    if total % 11 == 0:
        return "Right"
    # compute correct checksum digit
    sum_without_last = total - 10 * digits[9]
    correct_digit = None
    for d in range(11):
        if (sum_without_last + 10 * d) % 11 == 0:
            correct_digit = d
            break
    if correct_digit is None:
        return isbn  # should not happen
    # build corrected ISBN string
    corrected_parts = parts[:3] + [str(correct_digit) if correct_digit != 10 else 'X']
    return '-'.join(corrected_parts)

def process_random_numbers(numbers: List[int]) -> Tuple[int, List[int]]:
