    return len(unique_numbers), unique_numbers

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    terms = []
    for idx, coeff in enumerate(coeffs):
        if coeff == 0:
            continue
        degree = n - idx
        # Determine sign
        if not terms:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '-' if coeff < 0 else '+'
        abs_coeff = abs(coeff)
        # Coefficient part
        if abs_coeff == 1 and degree != 0:
            coeff_part = ''
        else:
            coeff_part = str(abs_coeff)
        # Variable part
        if degree > 1:
            var_part = f'x^{degree}'
        elif degree == 1:
            var_part = 'x'
        else:
            var_part = ''
        terms.append(f"{sign}{coeff_part}{var_part}")
    if not terms:
        return '0'
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    # Basic length check
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    reverse_mapping = {}

    for e, o in zip(encoded, original):
        # Check consistency for encoded -> original
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            # Ensure one-to-one mapping
            if o in reverse_mapping and reverse_mapping[o] != e:
                return "Failed"
            mapping[e] = o
            reverse_mapping[o] = e

    # All 26 letters must be represented in the mapping
    if len(mapping) != 26:
        return "Failed"

    # Decode the message
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded_chars.append(mapping[ch])

    return "".join(decoded_chars)

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to a maximum of 10 steps. Returns the minimum number of steps
    required to transform A into B, or "NO ANSWER!" if impossible within 10 steps.
    """
    if A == B:
        return 0

    from collections import deque

    max_depth = 10
    queue = deque([(A, 0)])
    visited = {A}

    while queue:
        current, steps = queue.popleft()
        if steps >= max_depth:
            continue  # do not explore deeper than 10 steps

        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return steps + 1
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                start = idx + 1  # allow overlapping matches

    return "NO ANSWER!"

def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    from collections import deque
    # Map each digit to the list of digits it can transform into
    rule_map = {}
    for x, y in rules:
        rule_map.setdefault(x, []).append(y)

    visited = {n}
    queue = deque([n])

    while queue:
        num = queue.popleft()
        s = str(num)
        for i, ch in enumerate(s):
            d = int(ch)
            if d in rule_map:
                for y in rule_map[d]:
                    new_s = s[:i] + str(y) + s[i+1:]
                    new_num = int(new_s)
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)
    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Helper to determine truth value of a statement
    def evaluate_statement(speaker: str, stmt: str) -> bool | None:
        # Ignore statements that mention any day of the week
        for day in days_of_week:
            if day in stmt:
                return None
        # Remove trailing period and strip whitespace
        stmt_clean = stmt.strip().rstrip('.')
        tokens = stmt_clean.split()
        if not tokens:
            return None
        # Handle "I am guilty." or "I am not guilty."
        if tokens[0] == "I" and len(tokens) >= 3 and tokens[1] == "am":
            if tokens[2] == "guilty":
                return scenario == speaker
            if tokens[2] == "not" and len(tokens) >= 4 and tokens[3] == "guilty":
                return scenario != speaker
        # Handle "<NAME> is guilty." or "<NAME> is not guilty."
        if len(tokens) >= 3 and tokens[1] == "is":
            target = tokens[0]
            if tokens[2] == "guilty":
                return scenario == target
            if tokens[2] == "not" and len(tokens) >= 4 and tokens[3] == "guilty":
                return scenario != target
        # If statement does not match expected patterns, ignore it
        return None

    for speaker, stmts in statements.items():
        for stmt in stmts:
            truth = evaluate_statement(speaker, stmt)
            if truth is None:
                continue  # ignore non-guilt statements or day-of-week statements
            is_liar = speaker in liar_count
            if is_liar:
                if truth:  # liar cannot make a true statement
                    return False
            else:
                if not truth:  # truth-teller cannot make a false statement
                    return False
    return True
